from course_model import *

SEED="""CREATE TYPE product_kind AS ENUM ('cake','pastry','icecream');
CREATE TABLE products(id serial PRIMARY KEY, name varchar(50) UNIQUE NOT NULL, description text, price numeric(8,2) NOT NULL CHECK(price>=0), weight integer NOT NULL CHECK(weight>=0), kind product_kind DEFAULT 'cake', calories integer NOT NULL CHECK(calories>=0), ingredients varchar[], diabetic_friendly boolean NOT NULL DEFAULT false, created_at timestamp DEFAULT current_timestamp);
INSERT INTO products(name,price,weight,kind,calories,ingredients,diabetic_friendly) VALUES ('Cake',12,200,'cake',400,ARRAY['flour','milk'],false),('Tea',4,100,'pastry',0,ARRAY['tea'],true),('Cookie',6,80,'pastry',250,ARRAY['flour'],false);
CREATE TYPE user_role AS ENUM ('admin','moderator','member');
CREATE TABLE users(id serial PRIMARY KEY, username varchar(50) UNIQUE NOT NULL, email varchar(100) NOT NULL, role user_role NOT NULL DEFAULT 'member', confirmed boolean DEFAULT false, created_at timestamp DEFAULT current_timestamp);
CREATE TABLE visits(id serial PRIMARY KEY, user_id integer NULL REFERENCES users(id), page varchar(500) NOT NULL, visited_at timestamp DEFAULT current_timestamp);
INSERT INTO users(username,email,role) VALUES ('Alex','alex@example.com','admin'),('Dana','dana@example.com','member');
INSERT INTO visits(user_id,page) VALUES (1,'/products'),(1,'/product/1'),(2,'/');"""

def Q(c,id,title,idea,code,expected,question,prompt,setup=SEED,check=None):
 lesson(c,id,title,idea,code,idea,question,sql(prompt,code,expected,setup,check))

c=chapter('sql-schema-complete','SQL · construiește schema de date','Produse, utilizatori și accesări, cu tipuri și constrângeri explicate separat.','prajituri.sql și utilizatori.sql; structura bazei pentru un site de produse','database')
Q(c,'schema-serial','Cheie generată cu serial','serial creează mecanismul pentru atribuirea implicită a unui întreg. PRIMARY KEY impune unicitate și absența valorilor NULL.','CREATE TABLE orders(id serial PRIMARY KEY, total numeric(8,2)); INSERT INTO orders(total) VALUES (12.50) RETURNING id;',[{'id':1}],q('Ce rol are PRIMARY KEY?','Identifică unic un rând și exclude NULL','Sortează automat rezultatul SELECT','Transformă textul în HTML'),'Creează orders cu id serial PRIMARY KEY și total numeric(8,2). Inserează total 12.50 și returnează id.',setup='')
Q(c,'schema-varchar','Text cu lungime maximă','varchar(50) limitează lungimea textului. text nu impune această limită declarată.','CREATE TABLE labels(name varchar(50)); SELECT character_maximum_length::int AS max_length FROM information_schema.columns WHERE table_name=\'labels\' AND column_name=\'name\';',[{'max_length':50}],q('Ce înseamnă 50 în varchar(50)?','Lungimea maximă declarată','Numărul de rânduri','Dimensiunea unei imagini'),'Creează labels cu o coloană name varchar(50) și citește character_maximum_length din information_schema.columns.',setup='')
Q(c,'schema-null','NULL înseamnă valoare necunoscută sau absentă','NULL nu este același lucru cu zero sau textul gol. Pentru testare folosește IS NULL, nu = NULL.',"SELECT name FROM products WHERE description IS NULL ORDER BY id;",[{'name':'Cake'},{'name':'Tea'},{'name':'Cookie'}],q('Cum testezi lipsa unei valori SQL?','IS NULL','= NULL','== null'),'Returnează name pentru produsele fără description, în ordinea id.')
Q(c,'schema-not-null','Coloană obligatorie','NOT NULL interzice lipsa unei valori în coloană. Nu interzice automat un text gol.','CREATE TABLE labels(name text NOT NULL); SELECT is_nullable FROM information_schema.columns WHERE table_name=\'labels\' AND column_name=\'name\';',[{'is_nullable':'NO'}],q('Interzice NOT NULL și textul gol?','Nu, este o regulă separată','Da, întotdeauna','Numai pentru text'),'Creează labels cu name text NOT NULL și citește is_nullable pentru acea coloană.',setup='')
Q(c,'schema-check','Regulă CHECK','CHECK validează o condiție pentru un rând. Folosește NOT NULL separat când lipsa valorii nu este permisă.','CREATE TABLE stock(quantity integer NOT NULL CHECK(quantity>=0)); INSERT INTO stock VALUES(3); SELECT quantity FROM stock;',[{'quantity':3}],q('Ce exprimă CHECK(quantity>=0)?','O regulă pentru valorile rândului','O comandă de sortare','Un filtru CSS'),'Creează stock cu quantity integer obligatoriu și nenegativ. Inserează 3 și afișează quantity.',setup='')
Q(c,'schema-unique','Valori unice','UNIQUE împiedică duplicatele conform regulilor constrângerii. Nu înlocuiește automat NOT NULL pentru o coloană obligatorie.','CREATE TABLE labels(name text UNIQUE NOT NULL); INSERT INTO labels VALUES (\'Cake\'); SELECT name FROM labels;',[{'name':'Cake'}],q('Ce constrângere declară unicitatea?','UNIQUE','DEFAULT','ORDER BY'),'Creează labels cu name text UNIQUE NOT NULL, inserează Cake și returnează name.',setup='')
Q(c,'schema-default','Valoare implicită','DEFAULT este folosit când coloana este omisă sau se cere explicit DEFAULT. Nu înlocuiește orice NULL introdus.','INSERT INTO users(username,email) VALUES (\'Mira\',\'mira@example.com\') RETURNING role::text AS role, confirmed;',[{'role':'member','confirmed':False}],q('Când se aplică valoarea DEFAULT în acest INSERT?','Când coloana este omisă','După orice SELECT','Numai când clientul trimite textul default'),'Adaugă Mira cu email mira@example.com, fără role sau confirmed. Returnează role ca text și confirmed.')
Q(c,'schema-numeric','Precizie și scară','numeric(8,2) permite până la 8 cifre totale și 2 zecimale. Valorile exacte de preț nu trebuie confundate cu numerele binare floating point.','SELECT price::text AS price FROM products WHERE name=\'Cake\';',[{'price':'12.00'}],q('Câte zecimale declară numeric(8,2)?','2','8','10'),'Citește prețul produsului Cake ca text, sub numele price.')
Q(c,'schema-boolean','Valori booleene','boolean stochează true, false sau NULL dacă nu există o restricție NOT NULL. Textele true și false nu sunt același tip în JavaScript.','SELECT name FROM products WHERE diabetic_friendly IS TRUE ORDER BY id;',[{'name':'Tea'}],q('Ce tip stochează adevărat/fals?','boolean','varchar obligatoriu','serial'),'Afișează name pentru produsele cu diabetic_friendly true.')
Q(c,'schema-array-literal','Liste într-o coloană PostgreSQL','ARRAY[...] construiește un vector SQL. O listă goală trebuie uneori convertită explicit la tipul dorit.','SELECT ARRAY[\'flour\',\'milk\']::text[] AS ingredients;',[{'ingredients':['flour','milk']}],q('Ce construiește ARRAY[...]?','Un vector SQL','Un tabel HTML','Un obiect Express'),'Returnează vectorul text flour, milk sub numele ingredients.',setup='')
Q(c,'schema-array-empty','Vector gol și NULL','Un vector gol există și are zero elemente; NULL reprezintă lipsa unei valori.','SELECT cardinality(ARRAY[]::text[]) AS count;',[{'count':0}],q('Este un vector gol același lucru cu NULL?','Nu','Da','Numai în PostgreSQL'),'Construiește un vector text gol și returnează cardinality ca count.',setup='')
Q(c,'schema-enum-values','Valorile permise ale unui ENUM','enum_range enumeră valorile tipului. unnest transformă vectorul rezultat în rânduri.','SELECT unnest(enum_range(NULL::product_kind))::text AS kind;',[{'kind':'cake'},{'kind':'pastry'},{'kind':'icecream'}],q('Ce face unnest aici?','Transformă elementele vectorului în rânduri','Șterge tipul','Sortează prețurile'),'Enumeră valorile product_kind într-o coloană kind de tip text.')
Q(c,'schema-time','Timestamp implicit','current_timestamp reprezintă momentul curent în contextul tranzacției. Nu memora în datele de test o oră fixă presupusă.','SELECT count(*)::int AS count FROM users WHERE created_at IS NOT NULL;',[{'count':2}],q('Ce oferă DEFAULT current_timestamp?','Un moment implicit pentru rând','Un id unic','O durată CSS'),'Numără utilizatorii care au created_at nenul și returnează count ca integer.')
Q(c,'schema-reference','Relație între tabele','REFERENCES leagă valoarea unei coloane de cheia din alt tabel. user_id din visits poate indica un utilizator existent.','SELECT users.username, visits.page FROM visits JOIN users ON users.id=visits.user_id ORDER BY visits.id;',[{'username':'Alex','page':'/products'},{'username':'Alex','page':'/product/1'},{'username':'Dana','page':'/'}],q('Ce leagă visits.user_id de users.id?','O cheie străină','O clasă CSS','O proprietate EJS'),'Afișează username și page pentru accesări, legând visits de users și ordonând după visits.id.')
Q(c,'schema-null-reference','Relație opțională','O cheie străină care permite NULL poate reprezenta o accesare fără utilizator autentificat. NULL nu este un id fals precum zero.','INSERT INTO visits(user_id,page) VALUES (NULL,\'/about\'); SELECT page FROM visits WHERE user_id IS NULL;',[{'page':'/about'}],q('Cum reprezentăm o accesare fără user când coloana permite?','Prin NULL','Prin orice id inexistent','Prin textul false'),'Adaugă accesarea anonimă /about și returnează paginile accesărilor cu user_id NULL.')
Q(c,'schema-if-not-exists','Creare repetabilă','IF NOT EXISTS evită eroarea de existență, dar nu actualizează automat structura unui tabel existent.','CREATE TABLE IF NOT EXISTS labels(name text); CREATE TABLE IF NOT EXISTS labels(name text); INSERT INTO labels VALUES (\'Cake\'); SELECT name FROM labels;',[{'name':'Cake'}],q('Actualizează CREATE TABLE IF NOT EXISTS automat schema existentă?','Nu','Da','Doar dacă are text'),'Creează labels(name text) de două ori cu IF NOT EXISTS, inserează Cake și citește name.',setup='')
Q(c,'schema-drop-type','Eliminarea unui tip de antrenament','DROP TYPE elimină definiția unui tip. Obiectele care depind de el trebuie tratate separat; nu folosi CASCADE fără să înțelegi consecințele.','CREATE TYPE training_kind AS ENUM(\'a\',\'b\'); DROP TYPE IF EXISTS training_kind; SELECT count(*)::int AS count FROM pg_type WHERE typname=\'training_kind\';',[{'count':0}],q('Ce elimină DROP TYPE?','Definiția tipului','Doar primul rând al unui tabel','Toate paginile web'),'Creează tipul training_kind cu valorile a,b, elimină-l și confirmă în pg_type că nu mai există, returnând count.',setup='')

c=chapter('sql-queries-complete','SQL · interogări și date pentru pagini','Filtre, agregări, actualizări și rezultate pentru un site de produse.','Interogările din server și schema produselor, utilizatorilor și accesărilor','database')
queries=[
 ('sql-select-columns','Alege coloanele','SELECT poate returna doar câmpurile necesare paginii.', 'SELECT name, weight FROM products ORDER BY id;',[{'name':'Cake','weight':200},{'name':'Tea','weight':100},{'name':'Cookie','weight':80}],'Returnează name și weight, în ordinea id.'),
 ('sql-distinct','Valori distincte','DISTINCT elimină rândurile duplicate din rezultatul selectat; nu modifică datele stocate.','SELECT DISTINCT kind::text AS kind FROM products ORDER BY kind;',[{'kind':'cake'},{'kind':'pastry'}],'Returnează tipurile de produs distincte ca text, ordonate după kind.'),
 ('sql-and-or','Condiții combinate','Parantezele clarifică gruparea dintre AND și OR.','SELECT name FROM products WHERE (kind=\'cake\' OR kind=\'pastry\') AND price>=6 ORDER BY id;',[{'name':'Cake'},{'name':'Cookie'}],'Alege produsele cake sau pastry cu preț de cel puțin 6; returnează name în ordinea id.'),
 ('sql-between','Interval inclusiv','BETWEEN include ambele limite. Pentru intervale semi-deschise scrie explicit >= și <.','SELECT name FROM products WHERE price BETWEEN 4 AND 6 ORDER BY id;',[{'name':'Tea'},{'name':'Cookie'}],'Returnează name pentru prețuri între 4 și 6 inclusiv, în ordinea id.'),
 ('sql-in-values','Apartenență la o listă','IN verifică dacă valoarea apare în lista dată.','SELECT name FROM products WHERE name IN (\'Tea\',\'Cake\') ORDER BY id;',[{'name':'Cake'},{'name':'Tea'}],'Selectează Cake și Tea folosind IN și ordonează după id.'),
 ('sql-ilike','Căutare fără diferență de registru','ILIKE face potrivire de tip LIKE fără diferență între litere mari și mici conform regulilor bazei. % reprezintă orice secvență.','SELECT name FROM products WHERE name ILIKE \'%CA%\' ORDER BY id;',[{'name':'Cake'}],'Caută nume care conțin CA indiferent de registru și returnează name.'),
 ('sql-coalesce','Valoare de rezervă','COALESCE întoarce prima valoare care nu este NULL; textul gol nu este automat NULL.','SELECT name, coalesce(description,\'No description\') AS description FROM products WHERE id=1;',[{'name':'Cake','description':'No description'}],'Pentru produsul 1, returnează name și description, folosind No description când description lipsește.'),
 ('sql-count-user-visits','Numără pe grupuri','GROUP BY grupează accesările, iar count numără rândurile grupului.','SELECT user_id, count(*)::int AS visits FROM visits GROUP BY user_id ORDER BY user_id;',[{'user_id':1,'visits':2},{'user_id':2,'visits':1}],'Returnează numărul de accesări pentru fiecare user_id, ordonat după user_id.'),
 ('sql-having','Filtrează grupurile','WHERE filtrează rânduri înainte de grupare; HAVING poate filtra grupurile după agregare.','SELECT user_id, count(*)::int AS visits FROM visits GROUP BY user_id HAVING count(*)>=2 ORDER BY user_id;',[{'user_id':1,'visits':2}],'Afișează doar utilizatorii cu cel puțin două accesări, cu user_id și visits.'),
 ('sql-returning','Valori după INSERT','RETURNING oferă datele rândurilor afectate fără un SELECT separat.','INSERT INTO products(name,price,weight,calories) VALUES (\'Bread\',8,300,600) RETURNING id,name;',[{'id':4,'name':'Bread'}],'Inserează Bread, preț 8, greutate 300, calorii 600 și returnează id,name.'),
 ('sql-update-returning','Valori după UPDATE','UPDATE ... RETURNING poate trimite direct noile valori către aplicație.','UPDATE products SET price=price+1 WHERE name=\'Tea\' RETURNING name,price::text AS price;',[{'name':'Tea','price':'5.00'}],'Mărește prețul Tea cu 1 și returnează name și noul price ca text.'),
 ('sql-delete-returning','Confirmă rândul eliminat','DELETE cu WHERE elimină doar rândurile potrivite. RETURNING arată ce a fost afectat.','DELETE FROM products WHERE name=\'Cookie\' RETURNING name;',[{'name':'Cookie'}],'Elimină Cookie și returnează name pentru rândul eliminat.'),
 ('sql-array-unnest','Ingrediente ca rânduri','unnest extinde vectorul de ingrediente. Un singur produs poate produce mai multe rânduri.','SELECT unnest(ingredients) AS ingredient FROM products WHERE name=\'Cake\';',[{'ingredient':'flour'},{'ingredient':'milk'}],'Returnează ingredientele Cake ca rânduri în coloana ingredient.'),
 ('sql-array-any','Caută în ingrediente','ANY compară o valoare cu elementele unui vector SQL.','SELECT name FROM products WHERE \'flour\'=ANY(ingredients) ORDER BY id;',[{'name':'Cake'},{'name':'Cookie'}],'Alege produsele cu flour în ingredients și returnează name în ordinea id.'),
 ('sql-pagination','Paginare deterministă','LIMIT și OFFSET au nevoie de ORDER BY pentru o ordine de afișare deterministă.','SELECT name FROM products ORDER BY id LIMIT 1 OFFSET 1;',[{'name':'Tea'}],'Returnează al doilea produs după id, cu LIMIT 1 OFFSET 1.'),
 ('sql-left-join','Păstrează și rândurile fără corespondent','LEFT JOIN păstrează rândurile din stânga chiar dacă lipsesc potriviri în dreapta.','INSERT INTO users(username,email) VALUES (\'Mira\',\'mira@example.com\'); SELECT u.username, count(v.id)::int AS visits FROM users u LEFT JOIN visits v ON u.id=v.user_id GROUP BY u.id,u.username ORDER BY u.id;',[{'username':'Alex','visits':2},{'username':'Dana','visits':1},{'username':'Mira','visits':0}],'Adaugă Mira fără accesări, apoi returnează username și numărul de visits pentru toți utilizatorii folosind LEFT JOIN.'),
]
for id,title,idea,code,expected,prompt in queries:
 Q(c,id,title,idea,code,expected,q('Ce descrie corect operația?',idea,'Schimbă automat fișierele CSS','Execută un template în browser'),prompt)

c=chapter('json-complete','JSON · transformări și cazuri speciale','Tipuri, erori, replacer, reviver și serializare.','JSON.pptx, 3–19','database')
def J(id,title,idea,body,cases,prompt):
 code='function solve(input) { '+body+' }'
 lesson(c,id,title,idea,code,idea,q('Ce regulă se aplică aici?',idea,'JSON execută metodele din text','Cheile nu au niciodată ghilimele'),js(prompt,code,cases))
J('json-full-types','Tipurile acceptate','JSON acceptă obiecte, vectori, texte, numere finite, true, false și null. Nu acceptă direct funcții sau undefined.','return JSON.parse(input);',[('[true,false,null,12,"Cake"]',[True,False,None,12,'Cake'])],'Parsează textul JSON și returnează structura rezultată.')
J('json-full-invalid','Tratează JSON invalid','JSON.parse aruncă o eroare pentru sintaxă invalidă. Nu confunda eșecul parsării cu o valoare null validă.','try { return {ok:true,value:JSON.parse(input)}; } catch { return {ok:false}; }',[('{"name":"Cake"}',{'ok':True,'value':{'name':'Cake'}}),('{name:"Cake"}',{'ok':False}),('null',{'ok':True,'value':None})],'Returnează {ok:true,value} pentru JSON valid sau {ok:false} pentru o eroare de parsare.')
J('json-full-undefined-object','undefined într-un obiect','La serializare, proprietățile unui obiect cu valoare undefined sunt omise.','return JSON.stringify({ name:input, missing:undefined });',[('Cake','{"name":"Cake"}')],'Serializează un obiect cu name din input și missing undefined.')
J('json-full-undefined-array','undefined într-un vector','Într-un vector, undefined este serializat ca null pentru a păstra poziția.','return JSON.stringify([input,undefined]);',[(3,'[3,null]')],'Serializează vectorul [input,undefined].')
J('json-full-nonfinite','Numere nefinite','NaN și Infinity devin null în JSON.stringify; nu sunt numere JSON valide scrise ca atare.','return JSON.stringify([NaN,Infinity,-Infinity]);',[(None,'[null,null,null]')],'Returnează serializarea vectorului [NaN,Infinity,-Infinity].')
J('json-full-root-reviver','Reviver și rădăcina','Reviver este apelat și pentru rezultatul final cu cheia goală. Dacă nu returnezi acea valoare, poți pierde rezultatul întreg.','return JSON.parse(input,(key,value)=>key==="price"?Number(value):value);',[('{"price":"12","name":"Cake"}',{'price':12,'name':'Cake'})],'Parsează JSON și convertește orice câmp price la Number, păstrând celelalte valori și rădăcina.')
J('json-full-replacer-function','Replacer ca funcție','O funcție replacer poate transforma valori în timpul serializării, fără să modifice obiectul inițial.','return JSON.stringify(input,(key,value)=>key==="price"?value*2:value);',[({'name':'Cake','price':12},'{"name":"Cake","price":24}')],'Dublează câmpurile price numai în JSON-ul produs de stringify.')
J('json-full-tojson','Metoda toJSON','Un obiect poate defini toJSON pentru reprezentarea sa serializată. Nu se serializează corpul funcției.','const product={name:input,toJSON(){return {label:this.name};}}; return JSON.stringify(product);',[('Cake','{"label":"Cake"}')],'Creează un obiect cu name din input și toJSON care întoarce {label:this.name}; serializează-l.')
J('json-full-date','Date și JSON','Date.toJSON produce în mod normal o reprezentare ISO pentru o dată validă. Parsarea JSON nu reconstruiește singură obiectul Date.','return JSON.stringify({date:new Date(input)});',[('2026-01-01T00:00:00Z','{"date":"2026-01-01T00:00:00.000Z"}')],'Serializează un obiect cu date construit din textul ISO input.')
J('json-full-circular','Referințe circulare','JSON.stringify nu poate serializa direct un ciclu între obiecte și aruncă o eroare.','const value={name:input}; value.self=value; try { JSON.stringify(value); return false; } catch { return true; }',[('Cake',True)],'Construiește un obiect care se referă la el însuși prin self. Returnează true dacă stringify aruncă o eroare.')

c=chapter('scss-complete','SCSS · module, liste și reutilizare','Configurare, funcții, bucle și selectori generați.','SASS.pptx, 3–29; SCSS-ul meniului și personalizarea componentelor','palette')
def S(id,title,idea,code,fixture,tests,prompt,files=None):
 task=css(prompt,code,fixture,tests,mode='scss')
 if files:task['files']=files
 lesson(c,id,title,idea,code,idea,q('Ce face construcția folosită?',idea,'Este executată de PostgreSQL','Este un tag HTML'),task)
S('sass-mixin','Mixin cu parametru','@mixin definește un grup de declarații reutilizabil, iar @include îl aplică.','@mixin spacing($size) { padding:$size; } .card { @include spacing(12px); }','<div class="card">Cake</div>',[prop('.card','padding-top','12px')],'Definește spacing($size) pentru padding și aplică-l pe .card cu 12px.')
S('sass-each','Iterează o listă cu @each','@each vizitează valorile unei liste. Interpolarea poate folosi valoarea în selector.','@each $name in cake, tea { .#{$name} { color:navy; } }','<p class="cake">Cake</p><p class="tea">Tea</p>',[prop('.cake','color','rgb(0, 0, 128)'),prop('.tea','color','rgb(0, 0, 128)')],'Generează clasele .cake și .tea cu color navy folosind @each.')
S('sass-list-length','Lungimea unei liste','sass:list oferă length; lista Sass are indici de la 1 când extragi elementele cu nth.','@use "sass:list"; $spaces:4px,8px,12px; .card { z-index:list.length($spaces); }','<div class="card">Cake</div>',[prop('.card','z-index','3')],'Setează z-index al .card la lungimea listei Sass 4px,8px,12px.')
S('sass-list-append','Adaugă într-o listă Sass','list.append produce o listă nouă. Atribuie rezultatul dacă vrei să folosești lista extinsă.','@use "sass:list"; $spaces:4px,8px; $spaces:list.append($spaces,12px); .card { padding:list.nth($spaces,3); }','<div class="card">Cake</div>',[prop('.card','padding-top','12px')],'Pornește de la lista 4px,8px, adaugă 12px și folosește al treilea element ca padding.')
S('sass-list-index','Caută într-o listă Sass','list.index întoarce poziția de la 1 sau null dacă valoarea lipsește.','@use "sass:list"; $names:cake,tea,cookie; .card { z-index:list.index($names,tea); }','<div class="card">Cake</div>',[prop('.card','z-index','2')],'Caută tea în lista cake,tea,cookie și folosește poziția ca z-index pentru .card.')
S('sass-for-exclusive','Diferența dintre to și through','@for ... to exclude limita superioară; through o include.','@for $index from 1 to 3 { .space-#{$index} { padding:$index*4px; } }','<div class="space-1">A</div><div class="space-2">B</div>',[prop('.space-1','padding-top','4px'),prop('.space-2','padding-top','8px')],'Generează doar clasele space-1 și space-2 cu padding 4px și 8px folosind @for from 1 to 3.')
S('sass-map','Valori numite într-o hartă','sass:map permite extragerea unei valori prin cheie; o hartă nu este același lucru cu lista de argumente a unei funcții.','@use "sass:map"; $colors:(accent:navy,background:white); .card { color:map.get($colors,accent); }','<p class="card">Cake</p>',[prop('.card','color','rgb(0, 0, 128)')],'Creează harta colors cu accent navy și background white; aplică accent pe .card.')

S('sass-forward','Reexportă un modul Sass','@forward expune membrii unui alt modul printr-un punct comun. Codul consumator folosește @use pe acel punct de intrare, fără să știe structura internă.','@use "theme"; .card { color:theme.$accent; }','<p class="card">Tea</p>',[prop('.card','color','rgb(0, 0, 128)')],'Fișierul theme reexportă tokens prin @forward. În codul tău, folosește @use "theme" și aplică theme.$accent pe .card.',files={'_theme.scss':'@forward "tokens";','_tokens.scss':'$accent:navy;'})

c=chapter('node-files-complete','Node · fișiere, căi și callback-uri','Construiește operații independente pe fișiere virtuale.','Node și Express - introducere.pptx, 19-32; operațiile de fișiere din server','file')
def N(id,title,idea,code,cases,prompt,files=None):
 lesson(c,id,title,idea,code,idea,q('Ce regulă aplici?',idea,'Browserul citește automat orice cale de pe disc','CSS creează directoarele'),js(prompt,code,cases,mode='node',files=files or {}))
N('node-path-parse','Descompune o cale','path.parse desparte o cale în root,dir,base,ext,name fără a citi fișierul.','const path=require("path"); function solve(input){const value=path.parse(input);return {name:value.name,ext:value.ext,dir:value.dir};}',[('/project/images/cake.webp',{'name':'cake','ext':'.webp','dir':'/project/images'})],'Primești o cale POSIX. Returnează name fără extensie, ext și dir folosind path.parse.')
N('node-path-absolute','Cale absolută sau relativă','path.isAbsolute verifică forma căii, nu existența resursei.','const path=require("path"); function solve(input){return path.isAbsolute(input);}',[('/project/cake.svg',True),('images/cake.svg',False)],'Returnează dacă input este o cale POSIX absolută.')
N('node-path-separator','Separatorul căii','path.sep este separatorul platformei; laboratorul folosește path.posix pentru rezultate deterministe.','const path=require("path"); function solve(input){return path.sep;} ',[(None,'/')],'Returnează path.sep pentru modulul POSIX furnizat.')
N('node-copy-file','Copiază înainte de înlocuire','copyFileSync copiază conținutul sursei în destinație. În acest laborator ambele fișiere sunt virtuale.','const fs=require("fs"); function solve(input){fs.copyFileSync("source.txt","backup.txt");return fs.readFileSync("backup.txt","utf8");}',[(None,'Original')],'Copiază source.txt în backup.txt și returnează conținutul copiei.',{'source.txt':'Original'})
N('node-list-directory','Listează un director','readdirSync întoarce numele intrărilor, nu conținutul fiecărui fișier. Ordonează-le explicit când ai nevoie de o ordine stabilă.','const fs=require("fs"); function solve(input){return fs.readdirSync("data").sort();}',[(None,['a.json','b.json'])],'Returnează numele fișierelor din directorul virtual data, ordonate alfabetic.',{'data/b.json':'{}','data/a.json':'{}'})
N('node-file-stat','Fișier sau director','lstatSync oferă metadate; isFile și isDirectory clasifică intrarea. O cale inexistentă trebuie tratată separat.','const fs=require("fs"); function solve(input){const info=fs.lstatSync(input);return {file:info.isFile(),directory:info.isDirectory()};}',[('data/a.json',{'file':True,'directory':False}),('data',{'file':False,'directory':True})],'Pentru o cale virtuală existentă, returnează {file,directory} folosind lstatSync.',{'data/a.json':'{}'})
N('node-read-callback','Rezultat asincron prin callback','Callback-ul fs primește eroarea ca prim argument. Transformă răspunsul într-o promisiune dacă vrei să îl aștepți cu await.','const fs=require("fs"); async function solve(input){return await new Promise((resolve,reject)=>fs.readFile("message.txt","utf8",(error,text)=>{if(error)reject(error);else resolve(text);}));}',[(None,'Hello')],'Citește message.txt prin readFile cu callback și întoarce textul dintr-o funcție async.',{'message.txt':'Hello'})
N('node-crypto-scrypt','Derivare de cheie','scryptSync derivă octeți dintr-un text și un salt. Lungimea în octeți diferă de lungimea reprezentării hex. Nu este o criptare reversibilă.','const crypto=require("crypto"); function solve(input){return crypto.scryptSync(input,"training-salt",16).toString("hex").length;}',[('Cake',32),('Tea',32)],'Derivă 16 octeți cu scryptSync din input și saltul training-salt; returnează lungimea textului hex.')

c=chapter('http-routing-complete','HTTP · construiește contractul rutelor','Metode, statusuri, prefixe, parametri și middleware.','Node și Express - introducere.pptx, 30–77','server')
def X(id,title,idea,routes,requests,prompt):
 code='const express=require("express");\nconst app=express();\n'+routes+'\nmodule.exports=app;'
 lesson(c,id,title,idea,code,idea,q('Ce regulă aplici în rută?',idea,'Orice cerere rulează toate metodele','URL-ul creează singur tabele SQL'),express(prompt,code,requests))
X('http-put','Metoda PUT','PUT și GET sunt metode distincte chiar dacă folosesc aceeași cale.','app.put("/product/1",(req,res)=>res.send("Updated"));',[dict(path='/product/1',method='PUT',bodyExpected='Updated')],'Răspunde la PUT /product/1 cu textul Updated.')
X('http-delete','Metoda DELETE','DELETE poate reprezenta eliminarea unei resurse; statusul și corpul răspunsului sunt alese explicit.','app.delete("/product/1",(req,res)=>res.status(204).end());',[dict(path='/product/1',method='DELETE',status=204,bodyExpected='')],'Răspunde la DELETE /product/1 cu status 204 și fără corp.')
X('http-multiple-paths','Mai multe căi pentru aceeași pagină','Un vector de căi poate trimite mai multe adrese către același handler.','app.get(["/","/home","/index"],(req,res)=>res.send("Home"));',[dict(path='/',bodyExpected='Home'),dict(path='/home',bodyExpected='Home'),dict(path='/index',bodyExpected='Home')],'Folosește un singur app.get cu vector de căi pentru /, /home și /index; toate răspund Home.')
X('http-regex-path','Potrivire cu expresie regulată','O expresie regulată poate selecta căi. Nu o confunda cu sintaxa unui șir de rută, care depinde de versiunea Express.',r'app.get(/^\/item\/[0-9]+$/,(req,res)=>res.send("Item")); app.use((req,res)=>res.status(404).send("Not found"));',[dict(path='/item/12',bodyExpected='Item'),dict(path='/item/abc',status=404,bodyExpected='Not found')],'Acceptă printr-o rută RegExp /item/ urmat numai de cifre. Răspunde Item; pentru orice altă cale, 404 Not found.')
X('http-two-params','Doi parametri în cale','Parametrii numiți sunt disponibili ca texte în req.params.','app.get("/category/:category/product/:id",(req,res)=>res.json({category:req.params.category,id:req.params.id}));',[dict(path='/category/cake/product/7',json={'category':'cake','id':'7'})],'Pentru /category/:category/product/:id, returnează JSON cu category și id exact cum vin în req.params.')
X('http-param-query','Parametru de cale și query împreună','req.params și req.query descriu părți diferite ale adresei.','app.get("/product/:id",(req,res)=>res.json({id:req.params.id,view:req.query.view||"full"}));',[dict(path='/product/7?view=compact',json={'id':'7','view':'compact'}),dict(path='/product/7',json={'id':'7','view':'full'})],'Returnează {id,view} pentru /product/:id, cu view din query sau full când lipsește.')
X('http-request-method','Citește metoda cererii','req.method arată metoda HTTP. Un middleware fără limitare la GET poate vedea mai multe metode.','app.use("/method",(req,res)=>res.send(req.method));',[dict(path='/method',bodyExpected='GET'),dict(path='/method',method='POST',bodyExpected='POST')],'La /method răspunde cu req.method pentru GET și POST.')
X('http-request-path','Calea fără query string','req.path nu include query string-ul. Pentru datele din query folosește req.query.','app.get("/products",(req,res)=>res.send(req.path));',[dict(path='/products?type=cake',bodyExpected='/products')],'La GET /products răspunde cu req.path, inclusiv când cererea are query string.')
X('http-locals','Date comune prin res.locals','res.locals transportă valori către handler-ele și template-urile aceleiași cereri. Middleware-ul trebuie să apeleze next pentru a continua.','app.use((req,res,next)=>{res.locals.siteName="Sweet Corner";next();}); app.get("/name",(req,res)=>res.send(res.locals.siteName));',[dict(path='/name',bodyExpected='Sweet Corner')],'Setează siteName Sweet Corner în res.locals prin middleware și afișează-l la /name.')
X('http-urlencoded','Date dintr-un formular','express.urlencoded parsează un corp formular. Trebuie înregistrat înainte de ruta care folosește req.body.','app.use(express.urlencoded({extended:false})); app.post("/message",(req,res)=>res.send(req.body.message));',[dict(path='/message',method='POST',headers={'Content-Type':'application/x-www-form-urlencoded'},body='message=Hello+web',bodyExpected='Hello web')],'Parsează un formular URL-encoded și returnează câmpul message la POST /message.')

c=chapter('templates-data-complete','EJS · transformă datele în pagini','Liste, condiții, formulare și fragmente reutilizabile.','views/pagini/*.ejs; views/fragmente/*.ejs; datele JSON și SQL','file')
def E(id,title,idea,code,data,tests,prompt):
 lesson(c,id,title,idea,code,idea,q('Ce rol are template-ul?',idea,'Interoghează singur orice bază SQL','Se execută direct ca CSS'),ejs(prompt,code,data,tests))
E('template-selected','Opțiunea selectată','selected poate fi emis condiționat pentru opțiunea care corespunde filtrului curent.','<select><% for(const value of categories){ %><option value="<%= value %>" <%= value===selected ? "selected" : "" %>><%= value %></option><% } %></select>',{'categories':['cake','pastry'],'selected':'pastry'},[attr('option[selected]','value','pastry'),count('option',2)],'Generează option pentru fiecare categorie și marchează selected doar categoria din selected.')
E('template-null-array','Ingrediente opționale','Un câmp SQL opțional poate ajunge null. O valoare de rezervă [] permite folosirea join fără eroare.','<p class="ingredients"><%= (product.ingredients || []).join(", ") %></p>',{'product':{'ingredients':None}},[exact('.ingredients','')],'Afișează ingredientele separate prin virgulă și spațiu; pentru null afișează text gol într-un p.ingredients.')
E('template-boolean','Text dintr-un boolean','Template-ul poate afișa etichete diferite fără să schimbe datele originale.','<p><%= product.diabetic_friendly ? "Sugar-free" : "Regular" %></p>',{'product':{'diabetic_friendly':True}},[exact('p','Sugar-free')],'Afișează Sugar-free când diabetic_friendly este true, altfel Regular, într-un paragraf.')
E('template-numeric','NUMERIC ca text','Un driver PostgreSQL poate returna prețul ca text. Convertește explicit înainte de formatarea aleasă pentru afișare.','<strong class="price"><%= Number(product.price).toFixed(2) %> EUR</strong>',{'product':{'price':'12.5'}},[exact('.price','12.50 EUR')],'Afișează product.price cu două zecimale și EUR într-un strong.price.')
E('template-counter','Numerotează rezultate','Indicele dintr-o buclă începe de la 0; pentru numerotare vizibilă de la 1 afișează index+1.','<ol><% products.forEach((product,index)=>{ %><li data-position="<%= index+1 %>"><%= product.name %></li><% }); %></ol>',{'products':[{'name':'Cake'},{'name':'Tea'}]},[attr('li:first-child','data-position','1'),attr('li:last-child','data-position','2'),exact('li:last-child','Tea')],'Generează o listă cu numele produselor și data-position de la 1.')
E('template-gallery-data','Datele galeriei devin markup','Template-ul primește obiectul galeriei pregătit de server. Folosește fiecare nume și legendă, fără căi personale de pe calculator.','<div class="gallery"><% for(const image of gallery.images){ %><figure><img src="<%= gallery.basePath + image.file %>" alt="<%= image.caption %>"><figcaption><%= image.caption %></figcaption></figure><% } %></div>',{'gallery':{'basePath':'/images/','images':[{'file':'cake.webp','caption':'Chocolate cake'}]}},[attr('.gallery img','src','/images/cake.webp'),attr('.gallery img','alt','Chocolate cake'),exact('figcaption','Chocolate cake')],'Generează figurile galeriei. Combină gallery.basePath cu image.file și afișează caption ca alt și figcaption.')
